contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the prover will call with arbitrary params
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // ensure this contract has enough balance to forward `value` if needed
        if (value > 0) {
            require(address(this).balance >= value, "not enough balance to forward");
        }

        // read observable pre-state
        uint256 minDelay = c.getMinDelay();

        // prepare id
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Try to schedule and record whether it reverted
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempt, observe timestamp and pending/ready/done flags
        uint256 ts = c.getTimestamp(id);
        bool isOp = c.isOperation(id);
        bool isPending = c.isOperationPending(id);
        bool isReady = c.isOperationReady(id);
        bool isDone = c.isOperationDone(id);

        // General property:
        // If schedule reverted then either delay < minDelay or operation already existed.
        // If schedule succeeded then the operation is pending (timestamp > DONE) and timestamp >= block.timestamp + delay
        // We cannot refer to block.timestamp inside assert beyond reading c state, but compare ts against block.timestamp + delay is allowed.
        // Compose assertion covering both cases.
        assert(
            (reverted && (delay < minDelay || !(!c.isOperation(id) || ts == 0)))
            || (!reverted && isOp && isPending && !isDone && ts >= block.timestamp + delay)
        );
    }

    // allow receiving Ether for forwarding to c
    receive() external payable {}
}

