contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call must supply a ready scheduled operation; we construct params and require preconditions
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // to allow forwarding ETH in execute, ensure this contract has enough balance
        if (value > 0) require(address(this).balance >= value, "insufficient balance to forward");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // require delay at least minDelay so schedule can succeed
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay, "delay too small");

        // The test runner deploys c and this contract is the caller for c calls below.
        // Ensure this contract has the PROPOSER_ROLE so schedule and cancel can be called if needed.
        // We cannot grant roles here, so require that this contract already has PROPOSER_ROLE and EXECUTOR_ROLE
        bytes32 PROPOSER = c.PROPOSER_ROLE();
        bytes32 EXECUTOR = c.EXECUTOR_ROLE();
        require(c.hasRole(PROPOSER, address(this)), "test contract lacks proposer role");
        require(c.hasRole(EXECUTOR, address(this)), "test contract lacks executor role");

        // Schedule the operation (this is a state-changing top-level call)
        c.schedule(target, value, data, predecessor, salt, delay);

        // Fast-forward condition for the prover: require that the scheduled timestamp is <= block.timestamp
        // i.e. the operation is ready now; getTimestamp is view
        uint256 ts = c.getTimestamp(id);
        require(ts > 1 && ts <= block.timestamp, "operation not ready immediately");

        // Now execute the operation (state-changing)
        // use try/catch to capture revert, but execution must be attempted as top-level call
        bool execReverted;
        try c.execute{value: value}(target, value, data, predecessor, salt) {
            execReverted = false;
        } catch {
            execReverted = true;
        }

        // After attempting execution: if it did not revert, the operation must be marked done
        bool done = c.isOperationDone(id);
        assert(execReverted || done);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try scheduling from this contract and assert that it reverts whenever this contract lacks PROPOSER_ROLE.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // We observe whether this test contract has the proposer role before attempting the state-changing call.
        bytes32 PROPOSER = c.PROPOSER_ROLE();
        bool isProposer = c.hasRole(PROPOSER, address(this));

        // The property we assert only concerns the case when this contract is NOT a proposer.
        require(!isProposer, "precondition: test contract must not have proposer role for this property");

        // Attempt to schedule and capture whether it reverts. The state-changing call must be a top-level statement.
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if caller lacks PROPOSER_ROLE, scheduling must revert.
        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
